const getCountryPromise = (api: Api) => {
    if (state.promise) {
        return state.promise;
    }
    state.promise = getMyCountry(getSilentApi(api)).catch(() => {
            return undefined;
        });
    return state.promise;
};

const useMyCountry = (): string | undefined => {
    const [country, setMyCountry] = useState<string | undefined>(undefined);
    const api = useApi();
    useEffect(() => {
        void getCountryPromise(api).then(setMyCountry);
    }, []);
    return country;
};

